import json
GENERATED_NAMES = {"checksums.json", "REPO-MAP.md", ".build-manifest.json"}
GENERATED_SUFFIXES = (".map", ".d.ts", ".checksum")
def generated_path(p):
    parts = p.split("/")
    return "dist" in parts[:-1] or parts[-1] in GENERATED_NAMES or parts[-1].endswith(GENERATED_SUFFIXES)
for n in ("pr-14","pr-15"):
    b=json.load(open(f"base/evals/fixtures/review-prs/manifests/{n}.json"))
    h=json.load(open(f"head/evals/fixtures/review-prs/manifests/{n}.json"))
    bk={(r["id"],r["file"],r["start"],r["end"]) for r in b["fix_regions"]}
    hk={(r["id"],r["file"],r["start"],r["end"]) for r in h["fix_regions"]}
    removed=bk-hk; added=hk-bk
    print(n, "removed", len(removed), "added", len(added))
    print("  removed non-generated:", [r for r in removed if not generated_path(r[1])])
    print("  remaining generated:", [r for r in h["fix_regions"] if generated_path(r["file"])])
    print("  defects same:", b["defects"]==h["defects"])
    # other keys same?
    print("  other keys same:", all(b[k]==h[k] for k in b if k!="fix_regions"))
EOF

